-- One-off fix: February 2025 audit ("2025 2 February System vs Source.xlsx").
-- Every February 2025 payment in the system is a day/month swap from Kibet's
-- "Payment Analysis ..." file - Excel read d/m/yyyy dates as m/d/yyyy:
--   * 1842 CHP stipends (KES 1954500), stored 2025-02-08 -> really 2 Sep 2025
--     (Q3 2025 sheet rows 3847-5688, between the 28/08 and 09/09 blocks).
--   * 8 Workshop/Conference - County L4 & 5 hospitals (KES 220800),
--     stored 2025-02-04 -> really 2 May 2025 (Q2 2025 sheet rows 302-309).
-- Request IDs come from the audit's "Date Corrections" sheet; all 1850 were
-- checked on the live DB (phone, amount and current date match, all Paid,
-- none flagged/recovered, nothing already on the target dates).
--
-- New dates are the TRUE payment dates (2025-09-02 / 2025-05-02), as the audit
-- says. NOTE: other imported rows are still stored one day early (SheetJS
-- 0.18.5 reads Excel dates at 23:59:44 the previous day in Africa/Nairobi).
-- When that importer bug is fixed and existing rows are shifted +1 day, these
-- rows must be EXCLUDED - they are listed in perdiem_requests_backup_2025_02_dates.
--
-- Before running: confirm against the SBM statement for 2 Sep and 2 May 2025.
-- NOT a numbered migration - run manually in the Supabase SQL Editor.
-- The whole thing runs in one transaction; any failed check rolls it all back.

begin;

create temp table date_fixes (id text primary key, old_date text not null, new_date text not null) on commit drop;

-- Step 1: Safety checks - every row must still be on its February date with
-- the audited totals.
do $$
declare n_chp int; s_chp double precision; n_ws int; s_ws double precision;
begin
  select count(*), coalesce(sum(p.total_perdiem), 0) into n_chp, s_chp
  from date_fixes f join perdiem_requests p on p.id = f.id and p.date = f.old_date
  where f.old_date = '2025-02-08' and p.event_id = 'bfd1d1a8-42da-45cb-a70c-65692e79e10c';
  select count(*), coalesce(sum(p.total_perdiem), 0) into n_ws, s_ws
  from date_fixes f join perdiem_requests p on p.id = f.id and p.date = f.old_date
  where f.old_date = '2025-02-04' and p.event_id = 'df4c9611-3800-4b5d-923b-3f7f95e0c131';
  if n_chp <> 1842 or s_chp <> 1954500 or n_ws <> 8 or s_ws <> 220800 then
    raise exception 'Safety check failed: CHP % rows / KES %, Workshop % rows / KES % (expected 1842 / 1954500, 8 / 220800)',
      n_chp, s_chp, n_ws, s_ws;
  end if;
end $$;

-- Step 2: Backup - old and new date for every changed row. Undo with:
--   update perdiem_requests p set date = b.old_date
--   from perdiem_requests_backup_2025_02_dates b where p.id = b.id;
create table perdiem_requests_backup_2025_02_dates as
  select f.id, f.old_date, f.new_date, now() as changed_at from date_fixes f;

-- Step 3: Move the payment dates.
do $$
declare n int;
begin
  update perdiem_requests p set date = f.new_date
  from date_fixes f where p.id = f.id and p.date = f.old_date;
  get diagnostics n = row_count;
  if n <> 1850 then raise exception 'Expected to update 1850 rows, updated %', n; end if;
end $$;

-- Step 4: Keep each event's date list in line - add the new date, drop the
-- February date once no payment on that event uses it.
update events e set event_dates = array_append(e.event_dates, x.new_date)
from (values ('bfd1d1a8-42da-45cb-a70c-65692e79e10c', '2025-09-02'),
             ('df4c9611-3800-4b5d-923b-3f7f95e0c131', '2025-05-02')) as x(event_id, new_date)
where e.id = x.event_id and not (x.new_date = any(e.event_dates));

update events e set event_dates = array_remove(e.event_dates, x.old_date)
from (values ('bfd1d1a8-42da-45cb-a70c-65692e79e10c', '2025-02-08'),
             ('df4c9611-3800-4b5d-923b-3f7f95e0c131', '2025-02-04')) as x(event_id, old_date)
where e.id = x.event_id
  and not exists (select 1 from perdiem_requests p where p.event_id = x.event_id and p.date = x.old_date);

commit;

-- Step 5: Verify - expect 0 rows in February 2025, 1842 / 1954500 on 2025-09-02,
-- 8 / 220800 on 2025-05-02, and 1850 rows in the backup table.
select count(*) as feb_2025_rows from perdiem_requests where date between '2025-02-01' and '2025-02-28';
select date, event_name, count(*), sum(total_perdiem) from perdiem_requests
where date in ('2025-09-02', '2025-05-02') group by date, event_name order by date;
select count(*) from perdiem_requests_backup_2025_02_dates;
